101		  // setup base DCRs
102	    const uint64_t startup_addr = 0x80000000;  // flat-image (vxbin/bin/hex) load address; the ELF path uses img.entry
103	    processor.dcr_write(VX_DCR_KMU_STARTUP_ADDR0, startup_addr & 0xffffffff);
104	  #if (VX_CFG_XLEN == 64)
105	    processor.dcr_write(VX_DCR_KMU_STARTUP_ADDR1, startup_addr >> 32);
106	  #endif
107	    processor.dcr_write(VX_DCR_KMU_STARTUP_ARG0, 0);
108	    processor.dcr_write(VX_DCR_KMU_STARTUP_ARG1, 0);
109	    processor.dcr_write(VX_DCR_KMU_GRID_DIM_X,   1);
110	    processor.dcr_write(VX_DCR_KMU_GRID_DIM_Y,   1);
111	    processor.dcr_write(VX_DCR_KMU_GRID_DIM_Z,   1);
112	    processor.dcr_write(VX_DCR_KMU_BLOCK_DIM_X,  1);
113	    processor.dcr_write(VX_DCR_KMU_BLOCK_DIM_Y,  1);
114	    processor.dcr_write(VX_DCR_KMU_BLOCK_DIM_Z,  1);
115	    processor.dcr_write(VX_DCR_KMU_LMEM_SIZE,    0);
116	    processor.dcr_write(VX_DCR_KMU_BLOCK_SIZE,   1);
117	    processor.dcr_write(VX_DCR_KMU_WARP_STEP_X,  VX_CFG_NUM_THREADS);
118	    processor.dcr_write(VX_DCR_KMU_WARP_STEP_Y,  0);
119	    processor.dcr_write(VX_DCR_KMU_WARP_STEP_Z,  0);
120	    processor.dcr_write(VX_DCR_KMU_CLUSTER_DIM_X, 1);
121	    processor.dcr_write(VX_DCR_KMU_CLUSTER_DIM_Y, 1);
122	    processor.dcr_write(VX_DCR_KMU_CLUSTER_DIM_Z, 1);
123	
124	    // load program
