126	    {
127	      std::string program_ext(fileExtension(program));
128	      if (isElfFile(program)) {
129	        // ELF executables (e.g. upstream riscv-tests) carry their own
130	        // entry point and the HTIF `tohost` pass/fail symbol.
131	        ElfImage img;
132	        if (!loadElfImage(program, ram, &img))
133	          return -1;
134	        monitor.attach(img);
135	        processor.dcr_write(VX_DCR_KMU_STARTUP_ADDR0, img.entry & 0xffffffff);
136	      #if (VX_CFG_XLEN == 64)
137	        processor.dcr_write(VX_DCR_KMU_STARTUP_ADDR1, img.entry >> 32);
138	      #endif
139	      } else if (program_ext == "vxbin") {
140	        ram.loadVxImage(program);
141	      } else if (program_ext == "bin") {
142	        ram.loadBinImage(program, startup_addr);
143	      } else if (program_ext == "hex") {
144	        ram.loadHexImage(program);
145	      } else {
146	        std::cerr << "Error: only ELF, *.vxbin, *.bin or *.hex images supported." << std::endl;
147	        return -1;
148	      }
149	    }
150	  #ifndef NDEBUG
151	    std::cout << "[VXDRV] START: program=" << program << std::endl;
152	  #endif
153	
154	    if (debug_mode) {
155	      // Debug mode: run RBB server in a tick loop until OpenOCD disconnects
156	      // and the program has completed naturally.
157	      std::cout << "[DEBUG] Starting debug mode on port " << rbb_port << std::endl;
158	
159	      DebugModule::set_verbose_logging(debug_verbose);
160	
161	      // Reset processor and kick the KMU. In normal run() mode these are
162	      // both done at the top of run(); debug mode replaces run() with its
163	      // own tick loop, so it must do them explicitly.
164	      processor.reset();
165	      processor.start_kmu();
166	
167	      Core* core = processor.get_first_core();
168	      if (core == nullptr) {
169	        std::cerr << "[DEBUG] no cores configured" << std::endl;
170	        return -1;
171	      }
172	
173	      // Prime warp 0's PC to the configured startup address. The Scheduler
174	      // sets warp PC only when the KMU dispatches a CTA, so for DTM debug
175	      // we initialize it directly before any cycle has run. The DCR-driven
176	      // dispatch path still works on resume via normal KMU scheduling.
177	      core->dtm_set_pc(0, static_cast<vortex::Word>(startup_addr));
178	
179	      DebugModule dm(core, &ram);
180	
181	      // Halt the hart at startup so the debugger can control execution.
182	      // Set DPC to the initial PC so the first RR of DPC reads correctly.
183	      vortex::Word initial_pc = core->dtm_get_pc(0);
184	      dm.set_debug_mode_enabled(true);
185	      dm.direct_write_register(0x7B1, initial_pc);
186	      dm.halt_hart(0);
187	
188	      jtag_dtm_t dtm(&dm);
189	      remote_bitbang_t rbb(rbb_port, &dtm);
190	
191	      std::cout << "[DEBUG] Remote bitbang server ready. Waiting for OpenOCD connection..." << std::endl;
192	
193	      bool program_completed_notified = false;
194	      bool ever_ran = false;
195	      while (true) {
196	        // Only advance the simulator while the hart is not halted by DTM;
197	        // honoring DM's halt state at the tick boundary implements halt/resume.
198	        if (!dm.hart_is_halted()) {
199	          SimPlatform::instance().tick();
200	          if (processor.any_running()) {
201	            ever_ran = true;
202	          }
203	        }
