207	        // (no clusters running and no in-flight channel packets) and notify
208	        // DebugModule once. The debugger can still resume / inspect after.
209	        if (ever_ran && !program_completed_notified && !processor.any_running()) {
210	          dm.notify_program_completed(core->dtm_get_pc(0));
211	          program_completed_notified = true;
212	        }
213	      }
214	      // Unreachable in practice; debug mode is a long-running session.
215	    } else if (monitor.enabled()) {
216	      // HTIF mode: tick until the test writes its `tohost` word, then
217	      // take the exit code from there. Used by upstream riscv-tests/isa.
218	      while (processor.cycle()) {
219	        if (monitor.tick(ram))
220	          break;
221	      }
222	      exitcode = monitor.exit_code();
223	    } else {
224	      // Drain the COUT ring every cycle; standalone simx has no host runtime,
225	      // so vx_printf output would stall on a full ring without this.
226	      // Constructing CoutDrainer with `ram` resets the ring on entry.
227	      CoutDrainer cout(ram);
228	      while (processor.cycle()) {
229	        cout.tick();
230	      }
231	      cout.tick(); // flush any remaining bytes
232	
233	      // flush GPU caches before reading back results
234	      {
235	        uint32_t dummy;
236	        for (uint32_t cid = 0; cid < VX_CFG_NUM_CORES * VX_CFG_NUM_CLUSTERS; ++cid) {
237	          processor.dcr_read(VX_DCR_BASE_CACHE_FLUSH, cid, &dummy);
238	        }
239	      }
240	
241	      // read exitcode from @MPM.1
242	      ram.read(&exitcode, VX_MEM_IO_EXIT_CODE, 4);
243	    }
244	  }
